//
// no noise no trig - genuay 27 (+ symmetry genuay 26)
//
// very much like https://www.shadertoy.com/view/XXVfRW just without cos/sin/atan

#define NO_TRIG // we brutally replace sin, cos by 2nd order parabula functions

#define ANIM

#define PI 3.1415926536

#ifdef NO_TRIG  // we brutally replace sin, cos by 2nd order parabula functions
// 2nd order parabulas
#define mysin(x) (.5-abs(fract((x)/PI/2.)-.5))*(.5-fract((x)/PI/2.))*16.
#define sin(x) mysin(x)
#define cos(x) mysin((x)+PI*.5)
#endif

mat2 ROTM(float ang) { return mat2(cos(ang),sin(ang),-sin(ang),cos(ang)); }

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 c=fragCoord-iResolution.xy*.5;
    c*=ROTM(iTime*.1);

    float MaxLevel=60.;
    float level = MaxLevel*(1.-exp(-iTime/10.));

    for(int i=0;i<=int(floor(level));i++) {
        float R=exp(-float(i)/20.); if (i==int(level)) R+=1./float(i+1)*(1.-fract(level));
        vec2 p=cos(float(i)
        #ifdef ANIM
        *(1.1-.1*(cos(max(0.,iTime-37.)*.2)*.5+.5))
        #endif
        -vec2(0,PI*.5))*iResolution.y*R*.3;
        vec2 n=normalize(-p);
        c-=p; 
        float cn=dot(c,n);
        c=c-cn*n+abs(cn)*n;
        c+=p;
    }

    fragColor.xyz=
        sin((length(c*.5)*2.3
            +(iTime-37.*1.)*((abs(level-MaxLevel)<1.5)?2.:0.)*vec3(1,1.03,1.05)
            )*(.5+.5-.5*exp(-iTime/10.))*sqrt(450./iResolution.y)
#ifndef NO_TRIG  // oh, and if no trigonometric functions are allowed, we have to get rid of atan, so no spirals ;(
            +atan(c.y,c.x)
#endif
            );            

    fragColor.w=1.;
}
